/// Markdown event iterator.
#[derive(Debug)]
pub struct Parser<'input, CB = DefaultParserCallbacks> {/* private fields */}

impl<'input, CB: ParserCallbacks<'input>> Parser<'input, CB> {
    /// Consumes the event iterator and produces an iterator that produces
    /// `(Event, Range)` pairs, where the `Range` value maps to the
    /// corresponding range in the markdown source.
    pub fn into_offset_iter(self) -> OffsetIter<'input, CB>;

    /// Creates an event iterator for the part of `text` from `from`, the
    /// start of a line that begins a top-level block, as if the document
    /// before it were already parsed. `resume` carries what that part
    /// learned: its link and footnote definitions, and its heading ids, so
    /// links resolve and ids number as in a parse of the whole. Source
    /// ranges index `text`.
    pub fn new_resumed(
        text: &'input str,
        options: Options,
        limits: Limits,
        from: usize,
        resume: &Resume,
        callbacks: CB,
    ) -> Self;

    /// Creates a new event iterator for markdown text with given options and
    /// callbacks.
    ///
    /// ```
    /// # use canopy_xmark::{BrokenLink, CowStr, Event, Options, Parser, ParserCallbacks, Tag};
    /// struct CustomCallbacks;
    /// impl<'input> ParserCallbacks<'input> for CustomCallbacks {
    ///     fn handle_broken_link(
    ///         &mut self,
    ///         link: BrokenLink<'input>,
    ///     ) -> Option<(CowStr<'input>, CowStr<'input>)> {
    ///         Some(("https://target".into(), link.reference))
    ///     }
    /// }
    ///
    /// let mut parser = Parser::new_with_callbacks("[broken]", Options::empty(), CustomCallbacks);
    ///
    /// assert!(matches!(
    ///     parser.nth(1),
    ///     Some(Event::Start(Tag::Link { .. }))
    /// ));
    /// ```
    ///
    /// See the [`ParserCallbacks`] trait for a list of callbacks that can be
    /// overridden.
    pub fn new_with_callbacks(text: &'input str, options: Options, callbacks: CB) -> Self;

    /// Creates a new event iterator for a markdown string with given options,
    /// callbacks, and bounds on its work. Past a bound, the parser stops:
    /// the block pass ends before it builds the whole document, and the
    /// events end. [`OffsetIter::limit_hit`] then says so.
    pub fn new_with_limits(
        text: &'input str,
        options: Options,
        limits: Limits,
        callbacks: CB,
    ) -> Self;

    /// Returns a reference to the internal `RefDefs` object, which provides
    /// access to the internal map of reference definitions.
    pub fn reference_definitions(&self) -> &RefDefs<'input>;
}

impl<'input, F> Parser<'input, BrokenLinkCallback<F>> {
    /// In case the parser encounters any potential links that have a broken
    /// reference (e.g `[foo]` when there is no `[foo]: ` entry at the bottom)
    /// the provided callback will be called with the reference name,
    /// and the returned pair will be used as the link URL and title if it is
    /// not `None`.
    ///
    /// This constructor is provided for backwards compatibility.
    /// This and other callbacks can also be customized with
    /// [`Parser::new_with_callbacks`].
    pub fn new_with_broken_link_callback(
        text: &'input str,
        options: Options,
        broken_link_callback: Option<F>,
    ) -> Self
    where
        F: FnMut(BrokenLink<'input>) -> Option<(CowStr<'input>, CowStr<'input>)>;
}

impl<'input> Parser<'input, DefaultParserCallbacks> {
    /// Creates a new event iterator for a markdown string without any options
    /// enabled.
    pub fn new(text: &'input str) -> Self;

    /// Creates a new event iterator for a markdown string with given options.
    pub fn new_ext(text: &'input str, options: Options) -> Self;
}

impl<'a, CB: ParserCallbacks<'a>> FusedIterator for Parser<'a, CB> {}

impl<'a, CB: ParserCallbacks<'a>> Iterator for Parser<'a, CB> {
    type Item = Event<'a>;
}

impl !Sync for Parser {}

/// Keeps track of the reference definitions defined in the document.
#[derive(Clone, Debug, Default)]
pub struct RefDefs<'input>(_, _);

impl<'input, 'b, 's> RefDefs<'input>
where
    's: 'b,
{
    /// Performs a lookup on reference label using unicode case folding.
    pub fn get(&self, key: &'b str) -> Option<&'b LinkDef<'input>>;

    /// Provides an iterator over all the document's reference definitions.
    pub fn iter(&self) -> impl Iterator<Item = (&'s str, &'s LinkDef<'input>)>;

    /// The source span of every reference definition, in source order. A
    /// label defined twice has both spans, though only the first takes
    /// effect and [`Self::iter`] gives only it.
    pub fn spans(&self) -> &[Range<usize>];
}

/// What a parse learned about a document, for parsing a later part of it on
/// its own with [`Parser::new_resumed`]: its link and footnote definitions,
/// and how its headings took their ids.
#[derive(Clone, Debug, Default)]
pub struct Resume {/* private fields */}

impl Resume {
    /// What the parse learned from the text before `at`.
    #[must_use]
    pub fn before(&self, at: usize) -> Self;

    /// Join what a parse of the text before a resume learned with what the
    /// resumed parse learned after it.
    #[must_use]
    pub fn then(self, after: Self) -> Self;
}

/// Returned when trying to convert a `&str` into a `InlineStr`
/// but it fails because it doesn't fit.
#[derive(Debug)]
pub struct StringTooLongError;

/// Tags for elements that can contain other elements.
#[derive(Clone, Debug, PartialEq)]
pub enum Tag<'a> {
    /// A paragraph of text and other inline elements.
    Paragraph,
    /// A heading, with optional identifier, classes and custom attributes.
    /// The identifier is prefixed with `#` and the last one in the attributes
    /// list is chosen, classes are prefixed with `.` and custom attributes
    /// have no prefix and can optionally have a value (`myattr` or
    /// `myattr=myvalue`).
    ///
    /// `id`, `classes` and `attrs` are only parsed and populated with
    /// [`Options::ENABLE_HEADING_ATTRIBUTES`], `None` or empty otherwise.
    Heading {
        level: HeadingLevel,
        id: Option<CowStr<'a>>,
        classes: Vec<CowStr<'a>>,
        /// The first item of the tuple is the attr and second one the value.
        ///
        /// Attribute names are not restricted: `# x {onclick=alert(1)}` gives
        /// `onclick`, which [`html::push_html`] writes to
        /// the output. These attributes don't arrive as [`Event::Html`] or
        /// [`Event::InlineHtml`], so dropping those events does not remove
        /// them.
        attrs: Vec<(CowStr<'a>, Option<CowStr<'a>>)>,
    },
    /// A block quote.
    ///
    /// The `BlockQuoteKind` is only parsed & populated with
    /// [`Options::ENABLE_GFM`], `None` otherwise.
    ///
    /// ```markdown
    /// > regular quote
    ///
    /// > [!NOTE]
    /// > note quote
    /// ```
    BlockQuote(Option<BlockQuoteKind>),
    /// An Obsidian callout, which is a block quote that opens with
    /// `[!label]`. Only parsed with [`Options::ENABLE_CALLOUTS`]; it takes
    /// the place of a GitHub alert's `BlockQuote(Some(kind))`.
    Callout(Callout<'a>),
    /// An Obsidian embed, `![[target]]`, whose content is its label: an
    /// image's alt text, or the label Obsidian shows. Only parsed with
    /// [`Options::ENABLE_OBSIDIAN_WIKILINKS`]; it takes the place of a
    /// wikilink image.
    Embed(Embed<'a>),
    /// A code block.
    CodeBlock(CodeBlockKind<'a>),
    ContainerBlock(ContainerKind, CowStr<'a>),
    /// An HTML block.
    ///
    /// A line that begins with some predefined tags (HTML block tags) (see [CommonMark Spec](https://spec.commonmark.org/0.31.2/#html-blocks) for more details) or any tag that is followed only by whitespace.
    ///
    /// Most HTML blocks end on an empty line, though some e.g. `<pre>` like
    /// `<script>` or `<!-- Comments -->` don't.
    /// ```markdown
    /// <body> Is HTML block even though here is non-whitespace.
    /// Block ends on an empty line.
    ///
    /// <some-random-tag>
    /// This is HTML block.
    ///
    /// <pre> Doesn't end on empty lines.
    ///
    /// This is still the same block.</pre>
    /// ```
    HtmlBlock,
    /// A list. If the list is ordered the field indicates the number of the
    /// first item. Contains only list items.
    List(Option<u64>),
    /// A list item.
    Item,
    /// A footnote definition. The value contained is the footnote's label by
    /// which it can be referred to.
    ///
    /// Only parsed and emitted with [`Options::ENABLE_FOOTNOTES`] or
    /// [`Options::ENABLE_OLD_FOOTNOTES`].
    FootnoteDefinition(CowStr<'a>),
    /// Only parsed and emitted with [`Options::ENABLE_DEFINITION_LIST`].
    DefinitionList,
    /// Only parsed and emitted with [`Options::ENABLE_DEFINITION_LIST`].
    DefinitionListTitle,
    /// Only parsed and emitted with [`Options::ENABLE_DEFINITION_LIST`].
    DefinitionListDefinition,
    /// A table. Contains a vector describing the text-alignment for each of its
    /// columns. Only parsed and emitted with [`Options::ENABLE_TABLES`].
    Table(Vec<Alignment>),
    /// A table header. Contains only `TableCell`s. Note that the table body
    /// starts immediately after the closure of the `TableHead` tag. There
    /// is no `TableBody` tag. Only parsed and emitted with
    /// [`Options::ENABLE_TABLES`].
    TableHead,
    /// A table row. Is used both for header rows as body rows. Contains only
    /// `TableCell`s. Only parsed and emitted with
    /// [`Options::ENABLE_TABLES`].
    TableRow,
    /// Only parsed and emitted with [`Options::ENABLE_TABLES`].
    TableCell,
    /// [Emphasis](https://spec.commonmark.org/0.31.2/#emphasis-and-strong-emphasis).
    /// ```markdown
    /// half*emph* _strong_ _multi _level__
    /// ```
    Emphasis,
    /// [Strong emphasis](https://spec.commonmark.org/0.31.2/#emphasis-and-strong-emphasis).
    /// ```markdown
    /// half**strong** __strong__ __multi __level____
    /// ```
    Strong,
    /// Only parsed and emitted with [`Options::ENABLE_STRIKETHROUGH`].
    ///
    /// ```markdown
    /// ~strike through~
    /// ```
    Strikethrough,
    /// Only parsed and emitted with [`Options::ENABLE_HIGHLIGHT`].
    ///
    /// ```markdown
    /// ==highlighted==
    /// ```
    Highlight,
    /// Only parsed and emitted with [`Options::ENABLE_SUPERSCRIPT`].
    ///
    /// ```markdown
    /// ^superscript^
    /// ```
    Superscript,
    /// Only parsed and emitted with [`Options::ENABLE_SUBSCRIPT`], if disabled
    /// `~something~` is parsed as [`Strikethrough`](Self::Strikethrough).
    /// ```markdown
    /// ~subscript~ ~~if also enabled this is strikethrough~~
    /// ```
    Subscript,
    /// A link.
    Link {
        link_type: LinkType,
        dest_url: CowStr<'a>,
        title: CowStr<'a>,
        /// Identifier of reference links, e.g. `world` in the link
        /// `[hello][world]`.
        id: CowStr<'a>,
    },
    /// An image. The first field is the link type, the second the destination
    /// URL and the third is a title, the fourth is the link identifier.
    Image {
        link_type: LinkType,
        dest_url: CowStr<'a>,
        title: CowStr<'a>,
        /// Identifier of reference links, e.g. `world` in the link
        /// `[hello][world]`.
        id: CowStr<'a>,
    },
    /// A metadata block.
    /// Only parsed and emitted with
    /// [`Options::ENABLE_YAML_STYLE_METADATA_BLOCKS`]
    /// or [`Options::ENABLE_PLUSES_DELIMITED_METADATA_BLOCKS`].
    MetadataBlock(MetadataBlockKind),
}

impl<'a> Tag<'a> {
    pub fn into_static(self) -> Tag<'static>;

    pub fn to_end(&self) -> TagEnd;
}

/// The end of a `Tag`.
#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
pub enum TagEnd {
    Paragraph,
    Heading(HeadingLevel),
    BlockQuote(Option<BlockQuoteKind>),
    Callout(BlockQuoteKind),
    Embed,
    CodeBlock,
    ContainerBlock(ContainerKind),
    HtmlBlock,
    /// A list, `true` for ordered lists.
    List(bool),
    Item,
    FootnoteDefinition,
    DefinitionList,
    DefinitionListTitle,
    DefinitionListDefinition,
    Table,
    TableHead,
    TableRow,
    TableCell,
    Emphasis,
    Strong,
    Strikethrough,
    Highlight,
    Superscript,
    Subscript,
    Link,
    Image,
    MetadataBlock(MetadataBlockKind),
}

impl<'a> From<Tag<'a>> for TagEnd {}

/// Where a watch stood after some part of a parse, so a watch of a parse
/// resumed there can carry on.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct TailMark {/* private fields */}

/// Reads the events of a parse, with their source ranges, to find a growing
/// document's open tail.
#[derive(Clone, Debug, Default)]
pub struct TailWatch {/* private fields */}

impl TailWatch {
    /// Start watching a parse resumed after a prefix whose watch left
    /// `mark`. Only the prefix's last block carries over: a quote that
    /// closed in the prefix holds nothing after it.
    #[must_use]
    pub fn after(mark: TailMark) -> Self;

    /// Where the watch stands, for resuming after what it read so far.
    #[must_use]
    pub fn mark(&self) -> TailMark;

    /// Start watching a parse.
    #[must_use]
    pub fn new() -> Self;

    /// Read the next event of the parse, with its source range.
    pub fn observe(&mut self, event: &Event<'_>, range: &Range<usize>);

    /// Return the open tail of `text`, the source the watched parse read,
    /// given the spans of its reference definitions.
    ///
    /// A trailing reference definition can gain a title on the next line,
    /// until a blank line or another block. A block is open until what ends
    /// it arrives: a closing fence and its line break, a blank line, the end
    /// of a heading's or a break's line, the closing delimiter of front
    /// matter or of an HTML block. A table stays open, since another row can
    /// follow.
    #[must_use]
    pub fn open_tail(&self, text: &str, definitions: &[Range<usize>]) -> Option<OpenTail>;
}

/// Merge consecutive `Event::Text` events into only one.
#[derive(Debug)]
pub struct TextMergeStream<'a, I> {/* private fields */}

impl<'a, I> TextMergeStream<'a, I>
where
    I: Iterator<Item = Event<'a>>,
{
    pub fn new(iter: I) -> Self;
}

impl<'a, I> Iterator for TextMergeStream<'a, I>
where
    I: Iterator<Item = Event<'a>>,
{
    type Item = Event<'a>;
}

/// Merge consecutive `Event::Text` events into only one, with offsets.
///
/// Compatible with with [`OffsetIter`](crate::OffsetIter).
#[derive(Debug)]
pub struct TextMergeWithOffset<'a, I> {/* private fields */}

impl<'a, I> TextMergeWithOffset<'a, I>
where
    I: Iterator<Item = (Event<'a>, Range<usize>)>,
{
    pub fn new(iter: I) -> Self;
}

impl<'a, I> Iterator for TextMergeWithOffset<'a, I>
where
    I: Iterator<Item = (Event<'a>, Range<usize>)>,
{
    type Item = (Event<'a>, Range<usize>);
}

/// Return the language a fence's info string names: its first word, which a
/// comma also ends, so `rust,ignore` names `rust`.
#[must_use]
pub fn fence_language(info: &str) -> Option<&str>;

/// Return the fenced code blocks of Markdown `text`, as CommonMark reads
/// them with [`Options::obsidian`]: in quotes and lists too, and not when
/// indented four spaces or more. A block with no content has no entry.
#[must_use]
pub fn fenced_code(text: &str) -> Vec<FencedCode<'_>>;

/// Return the properties of simple YAML front matter, as notes tools show
/// them: `key: value` lines, and lists written `[a, b]` or as `- item`
/// lines, which read as `a, b`. Front matter with nested maps, or anything
/// else, has none.
#[must_use]
pub fn front_matter_properties(yaml: &str) -> Option<Vec<(String, String)>>;

/// Return the id GitHub gives a heading with `text`: lowercase, with letters,
/// digits, `-`, and `_` kept, spaces as `-`, and everything else dropped.
///
/// Repeated ids take `-1`, `-2` suffixes in a document, which
/// [`Options::ENABLE_HEADING_IDS`](crate::Options::ENABLE_HEADING_IDS)
/// adds; this function gives the id alone.
#[must_use]
pub fn heading_slug(text: &str) -> String;

/// Return `text` with its Obsidian comments hidden, for a parser with
/// [`Options::ENABLE_COMMENTS`] to read.
///
/// A comment runs from one `%%` to the next, outside code and math; a `%%`
/// with no partner shows as written. A line that a comment hides entirely
/// turns blank, so it ends the paragraph it was in. Hidden bytes on a line
/// that keeps other text turn into a byte the parser removes. Every byte
/// keeps its offset, so source ranges into the result are ranges into
/// `text`. Text with no comment comes back borrowed.
#[must_use]
pub fn hide_comments(text: &str, options: Options) -> Cow<'_, str>;

/// Whether `path` names a Markdown file, by its extension.
#[must_use]
pub fn is_markdown(path: &Path) -> bool;

/// Decode `text`'s percent escapes. An escape that is not two hex digits
/// stays as written, and bytes that do not form UTF-8 become U+FFFD.
#[must_use]
pub fn percent_decode(text: &str) -> String;

/// Return the source range of the section of `text` that `anchor` names, as
/// Obsidian reads it with [`Options::obsidian`].
///
/// A `^id` names the block that holds that block id, the first such block.
/// Any other anchor names a heading: by its id, by the id it would take, or
/// by its text without regard to case. A heading's section runs to the next
/// heading of the same or a higher level, or to the end.
#[must_use]
pub fn section(text: &str, anchor: &str) -> Option<Range<usize>>;

/// Split a relative destination into its percent-decoded path and anchor,
/// dropping any query.
#[must_use]
pub fn split_destination(destination: &str) -> LinkTarget;

/// Split a wikilink's target into its path and `#` anchor, as Obsidian
/// reads them: trimmed, and not percent-decoded.
#[must_use]
pub fn split_wikilink(target: &str) -> LinkTarget;

/// Return the relative URL a wikilink to `target` names in an HTML page:
/// its path, with `.md` when it has no extension, and its anchor as the id
/// the page gives it. A heading anchor becomes its heading's id, and a block
/// anchor keeps its `^`.
#[must_use]
pub fn wikilink_href(target: &str) -> String;

/// Return the label Obsidian shows for an unlabelled wikilink to `target`:
/// its path without a `.md` extension, and its anchor after `›`.
#[must_use]
pub fn wikilink_label(target: &str) -> String;

